package jobq

import (
	"errors"
	"reflect"
	"testing"
)

var _ = errors.Is
var _ = reflect.DeepEqual

func vEnq(t *testing.T, q *Queue, name string, opts ...Option) int {
	t.Helper()
	id, err := q.Enqueue(name, "payload of "+name, opts...)
	if err != nil {
		t.Fatalf("Enqueue(%q): %v", name, err)
	}
	return id
}

func vTake(t *testing.T, q *Queue) Job {
	t.Helper()
	j, ok := q.Next()
	if !ok {
		t.Fatal("Next: nothing ready")
	}
	return j
}

func vTotal(q *Queue) int {
	n := 0
	for _, c := range q.Counts() {
		n += c
	}
	return n
}

func vState(t *testing.T, q *Queue, id int) string {
	t.Helper()
	j, err := q.Get(id)
	if err != nil {
		t.Fatal(err)
	}
	return j.State
}

func TestEnqueueAndNext(t *testing.T) {
	q := New()
	if _, ok := q.Next(); ok {
		t.Fatal("empty queue")
	}
	a := vEnq(t, q, "  first ")
	b := vEnq(t, q, "second")
	if a != 1 || b != 2 {
		t.Fatalf("ids %d %d", a, b)
	}
	if _, err := q.Enqueue("  ", "x"); !errors.Is(err, ErrBadName) {
		t.Fatalf("blank name: %v", err)
	}
	j := vTake(t, q)
	if j.ID != 1 || j.Name != "first" || j.State != Running || j.Payload != "payload of   first " {
		t.Fatalf("job %+v", j)
	}
	if got := vState(t, q, 2); got != Queued {
		t.Fatalf("second is %s", got)
	}
}

func TestCompleteFailCounts(t *testing.T) {
	q := New()
	vEnq(t, q, "a")
	vEnq(t, q, "b")
	vTake(t, q)
	vTake(t, q)
	if err := q.Complete(1); err != nil {
		t.Fatal(err)
	}
	if err := q.Fail(2, "boom"); err != nil {
		t.Fatal(err)
	}
	if err := q.Complete(1); !errors.Is(err, ErrState) {
		t.Fatalf("complete twice: %v", err)
	}
	if err := q.Fail(9, "x"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown: %v", err)
	}
	c := q.Counts()
	if c["queued"] != 0 || c["running"] != 0 || c["done"] != 1 || c["failed"] != 1 {
		t.Fatalf("counts %v", c)
	}
