	done, failed, _ := q.Drain(func(j Job) error {
		seen = append(seen, j.Name)
		if j.Name == "root" {
			return errors.New("no")
		}
		return nil
	})
	hEq(t, "handled", seen, []string{"root", "alone"})
	hEq(t, "counts", []int{done, failed}, []int{1, 1})
