	q := New()
	hEnq(t, q, "a", Priority(1))
	hEnq(t, q, "b", Priority(5))
	hEnq(t, q, "c", Priority(5))
	hEnq(t, q, "d")
	hEnq(t, q, "e", Priority(-3))
