func (q *Queue) Enqueue(name, payload string, opts ...Option) (int, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return 0, ErrBadName
	}
	j := &Job{ID: len(q.jobs) + 1, Name: name, Payload: payload, State: Queued}
	for _, o := range opts {
		if err := o(j); err != nil {
			return 0, err
		}
	}
	q.jobs = append(q.jobs, j)
	return j.ID, nil
}

