	hEq(t, "second", hTake(t, q).Name, "b")
	hEnq(t, q, "d")
	hEq(t, "third", hTake(t, q).Name, "c")
	hEq(t, "fourth", hTake(t, q).Name, "d")
	if _, ok := q.Next(); ok {
		t.Error("nothing left")
	}
	hEq(t, "state", hState(t, q, 1), Running)
}

