// Package jobq is a small deterministic in-memory job queue.
package jobq

import (
	"errors"
	"fmt"
	"strings"
)

// Job states.
const (
	Queued  = "queued"
	Running = "running"
	Done    = "done"
	Failed  = "failed"
	Canceled = "canceled"
)

var (
	ErrBadName   = errors.New("jobq: bad job name")
	ErrBadOption = errors.New("jobq: bad option")
	ErrNotFound  = errors.New("jobq: no such job")
	ErrState     = errors.New("jobq: wrong job state")
)

// Job is one unit of work.
type Job struct {
	ID      int
	Name    string
	Payload string
	State   string
	Reason  string
	Priority int
	Attempts    int
	MaxAttempts int
}

// Option changes a job while it is enqueued.
type Option func(*Job) error

// Priority makes a job more (or less) urgent; the default is 0.
func Priority(n int) Option {
	return func(j *Job) error {
		j.Priority = n
		return nil
	}
}

// MaxAttempts sets how often a job may be started (1 to 10).
func MaxAttempts(n int) Option {
	return func(j *Job) error {
		if n < 1 || n > 10 {
			return fmt.Errorf("%w: attempts must be between 1 and 10", ErrBadOption)
		}
		j.MaxAttempts = n
		return nil
	}
}

// Queue holds the jobs.
type Queue struct {
	jobs []*Job
}

// New returns an empty queue.
func New() *Queue {
	q := &Queue{}
	return q
}

// Enqueue adds a job and returns its id.
func (q *Queue) Enqueue(name, payload string, opts ...Option) (int, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return 0, ErrBadName
	}
	j := &Job{ID: len(q.jobs) + 1, Name: name, Payload: payload, State: Queued}
	j.MaxAttempts = 1
	for _, o := range opts {
		if err := o(j); err != nil {
			return 0, err
		}
	}
	q.jobs = append(q.jobs, j)
	return j.ID, nil
}

func (q *Queue) find(id int) (*Job, error) {
	if id < 1 || id > len(q.jobs) {
		return nil, fmt.Errorf("%w: %d", ErrNotFound, id)
	}
	return q.jobs[id-1], nil
}

func (q *Queue) isReady(j *Job) bool {
	if j.State != Queued {
		return false
	}
	return true
}

func better(a, b *Job) bool {
	if a.Priority != b.Priority {
		return a.Priority > b.Priority
	}
	return a.ID < b.ID
}

func (q *Queue) pick() *Job {
	var best *Job
	for _, j := range q.jobs {
		if q.isReady(j) && (best == nil || better(j, best)) {
			best = j
		}
	}
	return best
}

// Next starts the next ready job.
func (q *Queue) Next() (Job, bool) {
	j := q.pick()
	if j == nil {
		return Job{}, false
	}
	j.State = Running
	j.Attempts++
	return *j, true
}

// Complete marks a running job done.
func (q *Queue) Complete(id int) error {
	j, err := q.find(id)
	if err != nil {
		return err
	}
	if j.State != Running {
		return fmt.Errorf("%w: job %d is %s", ErrState, id, j.State)
	}
	j.State = Done
	return nil
}

// Fail marks a running job failed.
func (q *Queue) Fail(id int, reason string) error {
	j, err := q.find(id)
	if err != nil {
		return err
	}
	if j.State != Running {
		return fmt.Errorf("%w: job %d is %s", ErrState, id, j.State)
	}
	j.Reason = reason
	if j.Attempts < j.MaxAttempts {
		j.State = Queued
	} else {
		j.State = Failed
	}
	return nil
}

// Get returns a copy of a job.
func (q *Queue) Get(id int) (Job, error) {
	j, err := q.find(id)
	if err != nil {
		return Job{}, err
	}
	return *j, nil
}

// Counts returns the number of jobs in every state.
func (q *Queue) Counts() map[string]int {
	out := map[string]int{}
	for _, s := range []string{
		Queued, Running, Done, Failed,
		Canceled,
	} {
		out[s] = 0
	}
	for _, j := range q.jobs {
		out[j.State]++
	}
	return out
}

// Cancel cancels a queued job.
func (q *Queue) Cancel(id int) error {
	j, err := q.find(id)
	if err != nil {
		return err
	}
	if j.State != Queued {
		return fmt.Errorf("%w: job %d is %s", ErrState, id, j.State)
	}
	j.State = Canceled
	j.Reason = "canceled"
	return nil
}

